import{_ as e,a,o,a6 as i}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Attribute","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/shop/attributes/index.md","filePath":"api/rest-api/shop/attributes/index.md","lastUpdated":1787290888000}'),r={name:"api/rest-api/shop/attributes/index.md"};function s(n,t,d,l,h,c){return o(),a("div",null,t[0]||(t[0]=[i('<h1 id="attribute" tabindex="-1">Attribute <a class="header-anchor" href="#attribute" aria-label="Permalink to &quot;Attribute&quot;">​</a></h1><p>The Attribute menu exposes the catalog&#39;s attribute definitions — the named properties products carry (such as colour, size or brand) along with their selectable options and per-locale translations. Use it to build product filters, render variant selectors, and label attribute values in the shopper&#39;s language.</p><h2 id="attributes-options-and-translations" tabindex="-1">Attributes, Options and Translations <a class="header-anchor" href="#attributes-options-and-translations" aria-label="Permalink to &quot;Attributes, Options and Translations&quot;">​</a></h2><ul><li><strong>Attributes</strong> are the property definitions — <code>code</code>, <code>type</code>, and the flags that decide how each behaves.</li><li><strong>Attribute options</strong> are the selectable values of option-type attributes, such as the list of colours.</li><li><strong>Attribute translations</strong> hold the localised label for an attribute, keyed by locale.</li></ul><p>An attribute row already <strong>inlines its own <code>options</code></strong>, each with their translations. A filter UI or variant picker therefore needs one call, not one per attribute.</p><h2 id="the-flags-that-matter-to-a-client" tabindex="-1">The Flags That Matter to a Client <a class="header-anchor" href="#the-flags-that-matter-to-a-client" aria-label="Permalink to &quot;The Flags That Matter to a Client&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Flag</th><th>What it decides</th></tr></thead><tbody><tr><td><code>isFilterable</code></td><td>Whether the storefront filters on it. Only these belong in a facet list — an attribute existing does not mean the catalog can be narrowed by it.</td></tr><tr><td><code>isConfigurable</code></td><td>Whether variants are built from it, which is what a variant selector should render.</td></tr><tr><td><code>isVisibleOnFront</code></td><td>Whether the value belongs on a product page at all.</td></tr><tr><td><code>valuePerLocale</code> / <code>valuePerChannel</code></td><td>Whether the value changes with the request locale or channel — worth knowing before caching one.</td></tr><tr><td><code>type</code></td><td><code>text</code>, <code>select</code>, <code>multiselect</code>, <code>boolean</code>, <code>price</code>, and so on. Decides which input renders and whether <code>options</code> is populated.</td></tr></tbody></table><h2 id="no-filtering-on-these-endpoints" tabindex="-1">No Filtering on These Endpoints <a class="header-anchor" href="#no-filtering-on-these-endpoints" aria-label="Permalink to &quot;No Filtering on These Endpoints&quot;">​</a></h2><p>Neither collection accepts a filter. <code>?code=color</code> on the attribute list and <code>?attribute_id=23</code> on the options list are both accepted by the URL and ignored — every call returns the same first page. There is also no <code>/attributes/{id}/options</code> route.</p><p>To work with a single attribute, either fetch it by id at <code>GET /api/shop/attributes/{id}</code> and read its inline <code>options</code>, or page through the list and match on <code>code</code> client-side. The catalog carries roughly 42 attributes, so a full walk at <code>per_page=50</code> is a single request.</p><h2 id="how-these-feed-product-filtering" tabindex="-1">How These Feed Product Filtering <a class="header-anchor" href="#how-these-feed-product-filtering" aria-label="Permalink to &quot;How These Feed Product Filtering&quot;">​</a></h2><p>The product listing turns any filterable attribute code into a query parameter — <code>?color=3&amp;size=4,5</code> — and the values are <strong>option ids</strong>, not labels. That mapping is exactly what this menu provides: read <code>isFilterable</code>, take the attribute&#39;s <code>code</code> for the parameter name, and take <code>options[].id</code> for its value. See <a href="/api/rest-api/shop/products/search-product.html">Search Products</a>.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Method &amp; Path</th><th>Description</th></tr></thead><tbody><tr><td><a href="/api/rest-api/shop/attributes/get-attributes.html">Attributes</a></td><td><code>GET /api/shop/attributes</code></td><td>List attribute definitions.</td></tr><tr><td><a href="/api/rest-api/shop/attributes/get-attribute-options.html">Attribute Options</a></td><td><code>GET /api/shop/attribute-options</code></td><td>Flat collection of every option row.</td></tr><tr><td><a href="/api/rest-api/shop/attributes/get-attribute-translations.html">Attribute Translations</a></td><td><code>GET /api/shop/attribute_translations</code></td><td>Localised labels for an attribute.</td></tr></tbody></table><p>All Attribute endpoints are public reads that require only the storefront key — see <a href="/api/rest-api/authentication.html">Authentication</a>.</p>',15)]))}const b=e(r,[["render",s]]);export{u as __pageData,b as default};
